            format_price(product["price"]),
            product["category"]
        ]
        html_content += "            <tr>\n"
        for cell in row:
            html_content += f"                <td>{cell}</td>\n"
        html_content += "            </tr>\n"

    html_content += "        </tbody>\n    </table>\n\n"

