    return stock_quantity <= 0

def is_low_stock(stock_quantity):
    """Check if product has low stock (1-5 units)"""
    return stock_quantity > 0 and stock_quantity <= 5

def truncate_string(s, max_length, suffix="..."):
    """Truncate string to max length if needed"""
    if len(s) <= max_length:
        return s
    return s[:max_length - len(suffix)] + suffix

def truncate_sku(s, max_length):
    """Truncate SKU to maximum length"""
    # Remove leading zeros and truncate if necessary
    short_sku = s.replace('SKU-', '')
    if len(short_sku) > max_length:
