        lines.append(",".join(formatted_row))

    return "\n".join(lines) + "\n"

def generate_report(products):
    """Generate inventory audit report"""

    total_products = len(products)
    out_of_stock_products = [p for p in products if is_out_of_stock(p["stock_quantity"])]
    low_stock_products = [p for p in products if not is_out_of_stock(p["stock_quantity"]) and is_low_stock(p["stock_quantity"])]

    total_flagged = len(out_of_stock_products) + len(low_stock_products)

    # Calculate inventory metrics
    total_value = sum(p["price"] * p["stock_quantity"] for p in products)
    out_of_stock_value = sum(p["price"] * p["stock_quantity"] for p in out_of_stock_products)
    low_stock_value = sum(p["price"] * p["stock_quantity"] for p in low_stock_products)

    report = {
        "title": "Inventory Audit Report",
        "date": "March 6, 2026",
        "summary": {
            "total_products": total_products,
            "out_of_stock": len(out_of_stock_products),
            "low_stock_1_5": len(low_stock_products),
            "total_flagged": total_flagged
        },
        "out_of_stock_products": sorted(out_of_stock_products, key=lambda x: (x["stock_quantity"], x["id"])),
        "low_stock_products": sorted(low_stock_products, key=lambda x: (x["stock_quantity"], x["id"]))
    }

    return report, out_of_stock_products, low_stock_products

